template < class K >
inline
typename K::Boolean
x_equal(const Point_2<K> &p, const Point_2<K> &q)
{
  return internal::x_equal(p, q, K());
}

template < class K >
inline
typename K::Boolean
y_equal(const Point_2<K> &p, const Point_2<K> &q)
{
  return internal::y_equal(p, q, K());
}

